options.styles:
.frame-card {
  border: 1px solid rgba(127,127,127,0.3);
  border-radius: 4px;
  padding: 10px 12px;
  margin-bottom: 10px;
}
.frame-head { display: flex; justify-content: space-between; align-items: center; }
.serial { font-weight: 600; letter-spacing: 0.5px; }
.state { font-size: 11px; text-transform: uppercase; padding: 1px 6px; border-radius: 3px; background: rgba(200,60,60,0.35); }
.state.s-1 { background: rgba(60,160,90,0.35); }
.frame-meta { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; opacity: 0.8; margin-top: 6px; }
.kernel { opacity: 0.55; }
.badges { display: flex; gap: 6px; margin-top: 10px; flex-wrap: wrap; }
.badge { font-size: 11px; padding: 1px 6px; border-radius: 3px; background: rgba(200,60,60,0.35); }
.badge.b-1 { background: rgba(60,160,90,0.35); }

options.getOption:
const ctx = typeof context !== 'undefined' && context ? context : {};
const d =
  (typeof data !== 'undefined' && data) || (ctx.panel && ctx.panel.data) || {};
const th =
  (typeof theme !== 'undefined' && theme) || (ctx.grafana && ctx.grafana.theme) || {};
const text = (th.colors && th.colors.text) || {};
const textPrimary = text.primary || '#ccccdc';
const textSecondary = text.secondary || '#9a9aa5';

const axes = [
  { refId: 'A', name: 'CPU %', max: 100 },
  { refId: 'B', name: 'RAM %', max: 100 },
  { refId: 'C', name: 'Disk %', max: 100 },
  { refId: 'D', name: 'Temp \u00b0C', max: 85 },
  { refId: 'E', name: 'Load', max: 4 },
];

const read = (field, row) =>
  field.values && typeof field.values.get === 'function'
    ? field.values.get(row)
    : field.values[row];

const byFrame = {};
axes.forEach((axis, i) => {
  (d.series || [])
    .filter((s) => s.refId === axis.refId)
    .forEach((s) => {
      const valueField = s.fields.find((f) => f.type === 'number' && f.name !== 'Time');
      if (!valueField) return;
      const serialField = s.fields.find((f) => f.name === 'serial_number');
      const labelSerial =
        (valueField.labels && valueField.labels.serial_number) || null;
      const rows = valueField.values.length || 0;
      for (let r = 0; r < rows; r++) {
        const serial = serialField
          ? String(read(serialField, r))
          : labelSerial || s.name || 'frame';
        byFrame[serial] = byFrame[serial] || new Array(axes.length).fill(0);
        byFrame[serial][i] = Number(read(valueField, r)) || 0;
      }
    });
});

return {
  tooltip: { trigger: 'item' },
  legend: {
    bottom: 0,
    type: 'scroll',
    textStyle: { color: textPrimary },
  },
  radar: {
    indicator: axes.map((a) => ({ name: a.name, max: a.max })),
    axisName: { color: textSecondary },
    splitArea: { show: false },
  },
  series: [
    {
      type: 'radar',
      symbolSize: 4,
      areaStyle: { opacity: 0.1 },
      data: Object.keys(byFrame).map((k) => ({ name: k, value: byFrame[k] })),
    },
  ],
};
